head.script:

scwin.onpageload = function() {
	//progressbar1.set(14);
	//progressbar2.set(28);
	//progressbar3.set(30);
	//progressbar4.set(70);
	progressbar1.animate(0,100,3000,function(){console.log("finished1")});
	progressbar2.animate(0,100,3000,function(){console.log("finished2")});
	progressbar3.animate(0,30,3000,function(){console.log("finished3")});
	progressbar4.animate(0,45,3000,function(){console.log("finished4")});
};

scwin.onpageunload = function() {

};

scwin.checkVal1 = function() {
	return WebSquare.wUnit.getDomById('progressbar1_label').innerText == '100%';
}		
scwin.checkVal2 = function() {
	return WebSquare.wUnit.getDomById('progressbar4_label').innerText == '45%';
}		
scwin.unitTest = function() {
	//init
	WebSquare.wUnit.start();
	WebSquare.wUnit.addCommand("pause", "500");
	WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
	WebSquare.wUnit.addCommand("pause", "400");
	WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
	WebSquare.wUnit.addCommand("pause", "400");		
	//Run  and stop
	WebSquare.wUnit.run();
	WebSquare.wUnit.stop();
}
scwin.unitTest();
